    def get_component(r, c):
        q = deque([(r, c)])
        comp = []
        vis = {(r, c)}
        min_r, min_c, max_r, max_c = r, c, r, c

        while q:
            sr, sc = q.popleft()
            min_r = min(min_r, sr)
            min_c = min(min_c, sc)
            max_r = max(max_r, sr)
            max_c = max(max_c, sc)
            comp.append((sr, sc))

            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = sr + dr, sc + dc
                if in_bounds(nr, nc) and grid[nr][nc] == '.' and (nr, nc) not in vis:
                    vis.add((nr, nc))
                    q.append((nr, nc))

        return comp, min_r, min_c, max_r, max_c

    # Calculate current answer: convert all '*' inside any component's bounding box
    for r in range(n):
        for c in range(m):
            if grid[r][c] == '*':
                cnt = 0
                for rr in range(min_r_to_use := r, max_r_to_use := r + 1):
                    for cc in range(min_c_to_use := c, max_c_to_use := c + 1):
                        if in_bounds(rr, cc):
                            cnt += 0
                pass  # placeholder

    # More direct approach: identify all free space components
    vis = [[False] * m for _ in range(n)]
    components = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not vis[i][j]:
                vis[i][j] = True
                q = deque([(i, j)])
                comp = []
                min_r, min_c, max_r, max_c = i, j, i, j

                while q:
                    sr, sc = q.popleft()
                    comp.append((sr, sc))
                    min_r = min(min_r, sr)
                    min_c = min(min_c, sc)
                    max_r = max(max_r, sr)
                    max_c = max(max_c, sc)

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = sr + dr, sc + dc
                        if in_bounds(nr, nc) and grid[nr][nc] == '.' and not vis[nr][nc]:
                            vis[nr][nc] = True
                            q.append((nr, nc))

                components.append((comp, min_r, min_c, max_r, max_c))

    # Convert all '*' to '.' if the grid can be made all free
    # Check if all '*' are within some component's bounding box that should be filled
    # Actually, simpler: if there are walls, we might want to fill them to make room rectangular

    # Try two strategies:
    # 1. Don't remove any walls (current is valid if all rooms are rectangular)
    # 2. Remove all walls to make everything one big rectangle

    # Strategy 1: check if current is already valid
    def is_rectangle(comp):
        cnt = 0
        rows = max_r - min_r + 1
        cols = max_c - min_c + 1
        target = rows * cols
        for r, c in comp:
            if min_r <= r <= max_r and min_c <= c <= max_c:
                cnt += 1
        return cnt == target

    valid = True
    for comp, _, _, _, _ in components:
        if not is_rectangle(comp):
            valid = False
            break

    if valid:
        return grid_str.strip()

    # Strategy 2: convert entire grid to be one big rectangle containing all free spaces
    # Find overall bounding box of all free spaces
    all_r_min = n
    all_c_min = m
    all_r_max = -1
    all_c_max = -1

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.':
                all_r_min = min(all_r_min, r)
                all_c_min = min(all_c_min, c)
                all_r_max = max(all_r_max, r)
                all_c_max = max(all_c_max, c)

    if all_r_max == -1:  # No free spaces
        return grid_str.strip()

    # Convert all '*' in bounding box to '.'
    for r in range(all_r_min, all_r_max + 1):
        for c in range(all_c_min, all_c_max + 1):
            grid[r][c] = '.'

    return '\n'.join(''.join(row) for row in grid)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse events and extract segments (between type 1 events)
    segments = []
    current_segment = {}

    for line in lines[1:]:
        line = line.strip()
        if not line:
            continue
        if line == '1':
            if current_segment:
                segments.append(current_segment)
                current_segment = {}
        else:
            # Event 2 s
            parts = line.split()
            friend = parts[1]
            current_segment[friend] = True

    if current_segment:
        segments.append(current_segment)

    # Build conflict graph: two friends conflict if they appear in same segment
    conflict = {}
    for i in range(m):
        conflict[i] = set()

    # Collect all friends
    all_friends = set()
    for seg in segments:
        all_friends.update(seg.keys())

    # Map friend names to indices 0..(k-1) where k <= m
    friend_to_idx = {f: i for i, f in enumerate(sorted(all_friends))}
    k = len(all_friends)

    # Build adjacency matrix
    adj = [[0] * k for _ in range(k)]

    for seg in segments:
        friends = list(seg.keys())
        for i in range(len(friends)):
            for j in range(i + 1, len(friends)):
                f1, f2 = friends[i], friends[j]
                idx1, idx2 = friend_to_idx[f1], friend_to_idx[f2]
                adj[idx1][idx2] = 1
                adj[idx2][idx1] = 1

    # Maximum independent set using meet-in-the-middle
    # Since m <= 40 and typical cases are smaller, we split into two groups

    mid = k // 2

    # Left half: indices 0 to mid-1
    # Right half: indices mid to k-1

    # Generate all valid independent sets for each half
    def get_valid_sets(indices, adj_matrix):
        k = len(indices)
        valid = []
        n = len(indices)
        adj_local = [[0] * n for _ in range(n)]

        idx = {indices[i]: i for i in range(n)}
        for u in indices:
            for v in indices:
                if u <= v:
                    adj_local[idx[u]][idx[v]] = adj_matrix[u][v]

        # Find all independent sets
        for mask in range(1 << n):
            ok = True
            for i in range(n):
                if not (mask & (1 << i)):
                    continue
                for j in range(i + 1, n):
                    if mask & (1 << j) and adj_local[i][j]:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                valid.append(mask)
        return valid

    left_indices = list(range(mid))
    right_indices = list(range(mid, k))

    left_valid = get_valid_sets(left_indices, adj)
    right_valid = get_valid_sets(right_indices, adj)

    # Convert masks to actual independent sets
    def mask_to_set(mask, indices):
        result = []
        for i in range(len(indices)):
            if mask & (1 << i):
                result.append(indices[i])
        return result

    # Try all combinations
    max_size = 0

    for left_mask in left_valid:
        left_set = mask_to_set(left_mask, left_indices)

        for right_mask in right_valid:
            right_set = mask_to_set(right_mask, right_indices)

            # Check if the combined set is still independent
            combined_ok = True
            for u in left_set:
                for v in right_set:
                    if adj[u][v]:
                        combined_ok = False
                        break
                if not combined_ok:
                    break

            if combined_ok:
                max_size = max(max_size, len(left_set) + len(right_set))

    return str(max_size)

from collections import deque
from typing import List, Dict, Tuple, Optional

class Dinic:
    def __init__(self, n: int):
        self.n = n
        self.graph: List[List['__Edge']] = [[] for _ in range(n)]
        self.level = []

    class __Edge:
        def __init__(self, to: int, cap: int, rev: int):
            self.to = to
            self.cap = cap
            self.rev = rev

    def add_edge(self, u: int, v: int, cap: int):
        self.graph[u].append(self.__Edge(v, cap, len(self.graph[v])))
        self.graph[v].append(self.__Edge(u, 0, len(self.graph[u]) - 1))

    def bfs(self, s: int, t: int) -> bool:
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for e in self.graph[u]:
                if e.cap > 0 and self.level[e.to] < 0:
                    self.level[e.to] = self.level[u] + 1
                    queue.append(e.to)
        return self.level[t] >= 0

    def dfs(self, u: int, t: int, flow: int, ptr: List[int]) -> int:
        if flow == 0 or u == t:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            e = self.graph[u][i]
            if e.cap > 0 and self.level[u] < self.level[e.to]:
                pushed = self.dfs(e.to, t, min(flow, e.cap), ptr)
                if pushed > 0:
                    e.cap -= pushed
                    self.graph[e.to][e.rev].cap += pushed
                    return pushed
        return 0

    def max_flow(self, s: int, t: int) -> int:
        total = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                total += pushed
        return total


