class Dinic:
    def __init__(self, n: int):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u: int, v: int, cap: int) -> None:
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s: int, t: int) -> bool:
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, _ in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u: int, t: int, flow: int, ptr: List[int]) -> int:
        if flow == 0 or u == t:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if cap > 0 and self.level[v] == self.level[u] + 1:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s: int, t: int) -> int:
        total = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                total += pushed
        return total


def solve(n: int, m: int, a: List[int], b: List[int], roads: List[Tuple[int, int]]) -> Tuple[bool, List[List[int]]]:
    if sum(a) != sum(b):
        return False, []

    S = 0
    T = 2 * n + 1
    dinic = Dinic(T + 1)

    for i in range(n):
        dinic.add_edge(S, i, a[i])
        dinic.add_edge(T + n + i, T, b[i])
        dinic.add_edge(i, T + n + i, a[i])

    for u, v in roads:
        u -= 1
        v -= 1
        dinic.add_edge(u, T + n + v, a[u])
        dinic.add_edge(v, T + n + u, a[v])

    flow = dinic.max_flow(S, T)

    if flow != sum(a):
        return False, []

    adj = [[0] * n for _ in range(n)]
    for city in range(n):
        for e in dinic.graph[city]:
            if e[0] >= T + n:
                other = e[0] - (T + n)
                flow_orig = a[city]
                cap = e[1]
                if flow_orig - cap >= 0:
                    adj[city][other] = flow_orig - cap

    return True, adj


