def solve(n, wires):
    """
    wires: list of [x, y, wire_idx] where wire_idx is 1-based
    Returns: list of strings for output, or ["0"] if no operations needed
    """
    if n <= 1:
        return ["0"]

    # Union-Find for contact points
    parent = {}

    def find(x):
        if x not in parent or parent[x] != x:
            parent[x] = x
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    # Build connectivity from initial wires
    for w in wires:
        x, y, _ = w
        union(x, y)

    # Group wires by component
    comp_to_wires = defaultdict(list)
    for w in wires:
        x, y, w_idx = w
        root = find(x)
        comp_to_wires[root].append(w)

    # Get sorted component roots
    roots = sorted(list(comp_to_wires.keys()))
    k = len(roots) - 1

    return [str(k)] + generate_operations(roots, comp_to_wires, wires)

def generate_operations(roots, comp_to_wires, wires):
    """Generate re-soldering operations to connect components sequentially"""
    ops = []

    for i in range(len(roots) - 1):
        root_curr = roots[i]
        root_next = roots[i + 1]

        # Get a wire from each component
        w_curr = comp_to_wires[root_curr][0]
        w_next = comp_to_wires[root_next][0]

        e1_curr, e2_curr, w_idx = w_curr[0], w_curr[1], w_curr[2]
        e1_next, e2_next, _ = w_next[0], w_next[1], w_next[2]

        # Choose which endpoint to change (must change something in current component)
        if e1_curr != e1_next:
            # Can change to match next's first endpoint
            new_val = e1_next
        else:
            # Change to match next's second endpoint (different from first)
            new_val = e2_next

        ops.append(f"{w_idx} {e1_curr} {new_val}")

    return ops

