def solution(input_str):
    lines = input_str.strip().split('\n')
    n, h, m = map(int, lines[0].split())

    restrictions = []
    for i in range(1, m + 1):
        parts = list(map(int, lines[i].split()))
        l, r, x, c = parts
        restrictions.append((l, r, x, c))

    # Group restrictions by their right endpoint to check violations efficiently
    end_at = {}
    for i, (l, r, x, c) in enumerate(restrictions):
        if r not in end_at:
            end_at[r] = []
        end_at[r].append(i)

    # DP state: (position, current_max_for_each_active_restriction)
    # position goes from 1 to n+1
    # current_maxes[i] tracks max height in restriction[i]'s active range [l, min(r, pos-1)]

    @lru_cache(maxsize=None)
    def dp(pos, *current_maxes):
        # pos: current position to decide height for (1-indexed spots)
        # current_maxes: tuple of max heights for each restriction, only valid for restrictions where r >= pos

        if pos > n:
            # All positions filled, check one final violation (for restriction ending at n)
            # Actually violations would be checked when we move past each restriction's right endpoint
            return 0

        # Check violations for restrictions that just ended (at pos-1)
        # These are checked before deciding height for current position pos
        violation_penalty = 0
        for idx, req_idx in end_at.get(pos - 1, []):
            if req_idx < len(current_maxes) and current_maxes[req_idx] > restrictions[req_idx][2]:
                violation_penalty += restrictions[req_idx][3]

        max_profit = 0
        # Try all possible heights for the current position
        for h_val in range(h + 1):
            # Update current_maxes for restrictions that are still active (r >= pos)
            new_maxes = list(current_maxes)
            for i, (l, r, x, c) in enumerate(restrictions):
                if r >= pos:
                    if i < len(new_maxes):
                        new_maxes[i] = max(new_maxes[i], h_val)

            # Recurse to next position and add profit/penalty
            profit = violation_penalty + h_val * h_val + dp(pos + 1, *new_maxes)
            max_profit = max(max_profit, profit)

        return max_profit

    # Start DP: decide from position 1, all max heights initially 0
    initial_maxes = tuple(0 for _ in range(m))
    return str(dp(1, *initial_maxes))

from functools import lru_cache

def solution(n_str):
    n = int(n_str)

    if n == 0:
        return '0'

    @lru_cache(maxsize=None)
    def dp(num):
        # Base case
        if num == 0:
            return 0

        # Find the maximum digit in the current number
        max_digit = 0
        for char in str(num):
            d = int(char)
            if d > max_digit:
                max_digit = d

        # We must subtract a digit that is present in the number
        # Using the largest digit gives us the quickest reduction
        return 1 + dp(num - max_digit)

    return str(dp(n))

