import sys

def solution(input_string):
    lines = input_string.strip().split('\n')
    n, l, r = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))

    important = []
    unimportant = []

    for i in range(n):
        if b[i] == 1:
            important.append(a[i])
        else:
            unimportant.append(a[i])

    if not important:
        return "0\n"

    # Compute all achievable cumulative heights using only unimportant boxes
    total_unimportant = sum(unimportant)
    dp = [False] * (total_unimportant + 1)
    dp[0] = True
    for h in unimportant:
        for i in range(total_unimportant, h - 1, -1):
            if dp[i - h]:
                dp[i] = True

    # Sort important boxes ascending to maximize placement granularity
    important.sort()

    # Try each achievable unimportant height as starting position in [l, r]
    max_count = 0
    total = sum(unimportant) + sum(important)

    for start in range(l, min(r, total) + 1):
        if not dp[start]:
            continue

        current = start
        count = 0
        for size in important:
            if current + size <= r:
                count += 1
                current += size
            else:
                break

        max_count = max(max_count, count)

    return str(max_count) + '\n'

MOD = 10**9 + 7

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k, m = map(int, lines[0].split())

    if k == 1:
        return str(n % MOD)

    # Precompute factorial for optimization
    fact = [1] * (k + 1)
    for i in range(2, k + 1):
        fact[i] = fact[i - 1] * i % MOD

    def solve(n, k, m, mod, memo={}):
        memo_key = (n, k, m)
        if memo_key in memo:
            return memo[memo_key]

        if k == 1:
            result = n % mod
        elif k == 2:
            # Count all pairs (i, j) where j ≤ i + m and j ≠ i
            result = 0
            for i in range(1, n + 1):
                upper = min(n, i + m)
                # Available next positions in [1, upper] excluding i
                if upper >= i:
                    result = (result + upper - 1) % mod

        # For k > 2, we need to track visited planets
        return Result(n, k, m)

    class Result:
        def __init__(self, n, k, m):
            self.n = n
            self.k = k
            self.m = m
        def __repr__(self):
            return f"Result({self.n}, {self.k}, {self.m})"

    # Actually let's just use direct DFS since k is small (≤ 12)
    total = 0

    def dfs(current, visited):
        if len(visited) == k:
            return 1

        count = 0
        upper_bound = min(n, current + m)
        for next_pos in range(1, upper_bound + 1):
            if next_pos not in visited:
                visited.add(next_pos)
                count = (count + dfs(next_pos, visited)) % MOD
                visited.remove(next_pos)
        return count

    for start in range(1, n + 1):
        total = (total + dfs(start, {start})) % MOD

    return str(total)
